R (e.user_id = auth.uid())))))","roles":["authenticated"],"tablename":"employee_permissions","permissive":"PERMISSIVE","policyname":"Owners and employees can read assigned permissions","schemaname":"public","with_check":null},{"cmd":"ALL","qual":"((user_id = auth.uid()) AND user_owns_business(business_id))","roles":["authenticated"],"tablename":"angel_conversations","permissive":"RESTRICTIVE","policyname":"Angel author boundary","schemaname":"public","with_check":"((user_id = auth.uid()) AND user_owns_business(business_id))"},{"cmd":"ALL","qual":"(EXISTS ( SELECT 1\n   FROM angel_conversations c\n  WHERE ((c.id = angel_messages.conversation_id) AND (c.user_id = auth.uid()) AND user_owns_business(c.business_id))))","roles":["authenticated"],"tablename":"angel_messages","permissive":"RESTRICTIVE","policyname":"Angel message author boundary","schemaname":"public","with_check":"(EXISTS ( SELECT 1\n   FROM angel_conversations c\n  WHERE ((c.id = angel_messages.conversation_id) AND (c.user_id = auth.uid()) AND user_owns_business(c.business_id))))"},{"cmd":"SELECT","qual":"(user_owns_business(business_id) OR (requested_by = auth.uid()) OR private.has_business_permission(business_id, 'approve_credit'::text))","roles":["authenticated"],"tablename":"credit_approvals","permissive":"PERMISSIVE","policyname":"Credit approval scoped read","schemaname":"public","with_check":null},{"cmd":"SELECT","qual":"(user_owns_business(business_id) OR (requested_by = auth.uid()) OR private.has_business_permission(business_id, 'inspect_returns'::text) OR private.has_business_permission(business_id, 'approve_refund'::text))","roles":["authenticated"],"tablename":"sale_returns","permissive":"PERMISSIVE","policyname":"Return scoped read","schemaname":"public","with_check":null},{"cmd":"SELECT","qual":"(user_owns_business(business_id) OR (is_business_member(business_id) AND ((actor_id = auth.uid()) OR private.has_business_permission(business_id, 'view_finance'::text))))","roles":["authenticated"],"tablename":"offline_sale_reconciliations","permissive":"PERMISSIVE","policyname":"Offline reconciliation scoped read","schemaname":"public","with_check":null},{"cmd":"SELECT","qual":"(((user_id = auth.uid()) OR user_owns_business(business_id)) AND private.has_business_permission(business_id, 'view_inventory'::text))","roles":["authenticated"],"tablename":"pos_device_activity","permissive":"PERMISSIVE","policyname":"Own or owner device activity","schemaname":"public","with_check":null}]$targets$::jsonb;
 actual jsonb;policy jsonb;qual text;check_expression text;statement text;
 affected_tables text[]:=array['angel_conversations','angel_messages','audit_logs','business_members','businesses','credit_approvals','employee_permissions','employees','offline_sale_reconciliations','pos_device_activity','recordings','sale_returns'];
 changed integer:=0;calls integer:=0;
begin
 -- Do not queue blocking DDL behind application work.
 lock table public.angel_conversations,public.angel_messages,public.audit_logs,public.business_members,public.businesses,public.credit_approvals,public.employee_permissions,public.employees,public.offline_sale_reconciliations,public.pos_device_activity,public.recordings,public.sale_returns
  in access exclusive mode nowait;

 if md5(pg_get_functiondef('auth.uid()'::regprocedure))<>'ea3b41bf29e2ad573067939329aa088e'
 or (select provolatile from pg_proc where oid='auth.uid()'::regprocedure)<>'s' then
  raise exception 'auth.uid definition/stability drift';
 end if;

 select jsonb_agg(to_jsonb(p) order by schemaname,tablename,policyname) into actual
 from pg_policies p where schemaname='public' and tablename=any(affected_tables);
 if actual is distinct from expected_policies then
  raise exception 'Policy scope changed; review all protected boundaries before retrying';
 end if;
 select jsonb_agg(jsonb_build_object('schema',n.nspname,'table',c.relname,
  'acl',c.relacl::text,'rls',c.relrowsecurity,'forced_rls',c.relforcerowsecurity,
  'owner',pg_get_userbyid(c.relowner)) order by n.nspname,c.relname) into actual
 from pg_class c join pg_namespace n on n.oid=c.relnamespace
 where n.nspname='public' and c.relkind in ('r','p') and c.relname=any(affected_tables);
 if actual is distinct from expected_tables then
  raise exception 'Table ownership/grant/RLS drift';
 end if;
 if jsonb_array_length(targets)<>20 then raise exception 'Expected exactly 20 policies';end if;

 for policy in select value from jsonb_array_elements(targets) loop
  qual:=policy->>'qual';check_expression:=policy->>'with_check';
  calls:=calls+(coalesce(length(qual)-length(replace(qual,'auth.uid()','')),0)
   +coalesce(length(check_expression)-length(replace(check_expression,'auth.uid()','')),0))/length('auth.uid()');
 end loop;
 if calls<>25 then raise exception 'Expected exactly 25 uid-call replacements';end if;

 for policy in select value from jsonb_array_elements(targets) loop
  qual:=policy->>'qual';check_expression:=policy->>'with_check';
  statement:=format('alter policy %I on %I.%I',
   policy->>'policyname',policy->>'schemaname',policy->>'tablename');
  if qual is not null then
   statement:=statement||' using ('||replace(qual,'auth.uid()','(select auth.uid())')||')';
  end if;
  if check_expression is not null then
   statement:=statement||' with check ('||replace(check_expression,'auth.uid()','(select auth.uid())')||')';
  end if;
  -- No TO clause, CREATE/DROP POLICY, mode/command change or helper rewriting.
  execute statement;
  changed:=changed+1;
 end loop;
 if changed<>20 then raise exception 'Unexpected policy-change count';end if;
end;
$optimize$;
